            avg_confidence = sum(confidences) / len(confidences) if confidences else 0.0
            return {
                "text": text,
                "word_count": len(text.split()),
                "confidence": avg_confidence,
                "language": "hun+eng",
                "method": "tesseract_ocr"
            }
        except Exception as e:
