class MinHashDeduplicator:
    def __init__(self, threshold: float = 0.8, num_perm: int = 128):
        self.threshold = threshold
        self.num_perm = num_perm
        self.lsh = MinHashLSH(threshold=threshold, num_perm=num_perm)
        self.seen_hashes: Dict[str, MinHash] = {}

    def is_duplicate(self, doc_id: str, text: str) -> bool:
        minhash = self._compute_minhash(text)
        similar = self.lsh.query(minhash)
        if similar:
            return True
        self.lsh.insert(doc_id, minhash)
        self.seen_hashes[doc_id] = minhash
        return False

    def _compute_minhash(self, text: str) -> MinHash:
        minhash = MinHash(num_perm=self.num_perm)
        tokens = text.lower().split()
        for token in tokens:
            minhash.update(token.encode('utf-8'))
        return minhash

class TemporalTopicDivergence:
    def __init__(self, window_size: int = 100, divergence_threshold: float = 0.5):
        self.window_size = window_size
        self.threshold = divergence_threshold
        self.topic_history: List[Dict[str, float]] = []

    def add_document_topics(self, topics: Dict[str, float]):
        self.topic_history.append(topics)
        if len(self.topic_history) > self.window_size * 2:
            self.topic_history.pop(0)

    def detect_shift(self) -> Tuple[bool, float]:
        if len(self.topic_history) < self.window_size * 2:
            return False, 0.0
        recent = self.topic_history[-self.window_size:]
        previous = self.topic_history[-self.window_size*2:-self.window_size]
        recent_dist = self._aggregate_distribution(recent)
        previous_dist = self._aggregate_distribution(previous)
        kl_div = self._kl_divergence(previous_dist, recent_dist)
        is_shift = kl_div > self.threshold
        return is_shift, kl_div

    def _aggregate_distribution(self, topic_list: List[Dict[str, float]]) -> np.ndarray:
        all_topics = set()
        for topics in topic_list:
            all_topics.update(topics.keys())
        topic_index = {topic: i for i, topic in enumerate(sorted(all_topics))}
        dist = np.zeros(len(topic_index))
        for topics in topic_list:
            for topic, prob in topics.items():
                dist[topic_index[topic]] += prob
        dist = dist / (dist.sum() + 1e-10)
        return dist

    def _kl_divergence(self, p: np.ndarray, q: np.ndarray) -> float:
        p = p + 1e-10
        q = q + 1e-10
        p = p / p.sum()
        q = q / q.sum()
        return entropy(p, q)

class EntityGraphNoveltyDetector:
    def __init__(self):
        self.entities: Set[str] = set()
        self.edges: Set[Tuple[str, str, str]] = set()

    def add_entity(self, entity: str):
        self.entities.add(entity)

    def add_edge(self, entity1: str, relation: str, entity2: str) -> bool:
        edge = (entity1, relation, entity2)
        if edge in self.edges:
            return False
        self.edges.add(edge)
        self.entities.add(entity1)
        self.entities.add(entity2)
        return True

    def get_entity_degree(self, entity: str) -> int:
        degree = 0
        for e1, _, e2 in self.edges:
            if e1 == entity or e2 == entity:
                degree += 1
        return degree

class NoveltyPipeline:
    def __init__(self, output_dir: str = "novelty_data"):
        self.deduplicator = MinHashDeduplicator()
        self.topic_divergence = TemporalTopicDivergence()
        self.entity_graph = EntityGraphNoveltyDetector()
        self.output_dir = Path(output_dir)
        self.output_dir.mkdir(exist_ok=True, parents=True)
        self.novel_docs: List[Dict] = []

    def process_document(self, doc_id: str, text: str, topics: Dict[str, float],
                        entities: List[Tuple[str, str, str]]) -> Dict:
        result = {
            "doc_id": doc_id,
            "is_duplicate": False,
            "topic_shift": False,
            "new_edges": 0,
            "novelty_score": 0.0,
        }
        if self.deduplicator.is_duplicate(doc_id, text):
            result["is_duplicate"] = True
            result["novelty_score"] = 0.0
            return result
        self.topic_divergence.add_document_topics(topics)
        topic_shift, kl_div = self.topic_divergence.detect_shift()
        result["topic_shift"] = topic_shift
        result["kl_divergence"] = kl_div
        new_edges = 0
        for e1, relation, e2 in entities:
            if self.entity_graph.add_edge(e1, relation, e2):
                new_edges += 1
        result["new_edges"] = new_edges
        novelty_score = 0.0
        if not result["is_duplicate"]:
            novelty_score += 0.3
        if topic_shift:
            novelty_score += 0.3
        novelty_score += min(new_edges * 0.1, 0.4)
        result["novelty_score"] = novelty_score
        if novelty_score > 0.5:
            self.novel_docs.append({"doc_id": doc_id, "score": novelty_score})
        return result

@dataclass
