class KnowledgeGraph:
    def __init__(self, graph_file: Optional[str] = None):
        self.graph = nx.MultiDiGraph()
        self.entities: Dict[str, Entity] = {}
        self.graph_file = Path(graph_file) if graph_file else Path("knowledge_graph.json")
        if self.graph_file.exists():
            self.load()

    def add_entity(self, entity: Entity):
        self.entities[entity.entity_id] = entity
        self.graph.add_node(entity.entity_id, **entity.attributes, type=entity.entity_type)

    def add_relation(self, relation: Relation):
        if relation.source_id not in self.entities:
            return
        if relation.target_id not in self.entities:
            return
        self.graph.add_edge(
            relation.source_id,
            relation.target_id,
            key=relation.relation_type,
            type=relation.relation_type,
            confidence=relation.confidence,
            timestamp=relation.timestamp,
            **relation.metadata
        )

    def predict_links(self, entity_id: str, top_k: int = 10) -> List[Tuple[str, float]]:
        if entity_id not in self.graph:
            return []
        candidates = []
        existing_neighbors = set(self.graph.successors(entity_id)) | set(self.graph.predecessors(entity_id))
        for node in self.graph.nodes():
            if node == entity_id or node in existing_neighbors:
                continue
            node_neighbors = set(self.graph.successors(node)) | set(self.graph.predecessors(node))
            common = len(existing_neighbors & node_neighbors)
            degree_product = self.graph.degree(entity_id) * self.graph.degree(node)
            score = common * 0.6 + np.log1p(degree_product) * 0.4
            if score > 0:
                candidates.append((node, score))
        candidates.sort(key=lambda x: x[1], reverse=True)
        return candidates[:top_k]

    def prioritize_leads(self) -> List[Tuple[str, float]]:
        if not self.graph.nodes():
            return []
        try:
            betweenness = nx.betweenness_centrality(self.graph)
            pagerank = nx.pagerank(self.graph)
        except:
            betweenness = {node: 0.0 for node in self.graph.nodes()}
            pagerank = {node: 1.0 / len(self.graph.nodes()) for node in self.graph.nodes()}
        lead_scores = []
        for node in self.graph.nodes():
            degree = self.graph.degree(node)
            score = (betweenness.get(node, 0) * 0.4 +
                    pagerank.get(node, 0) * 0.3 +
                    np.log1p(degree) * 0.3)
            lead_scores.append((node, score))
        lead_scores.sort(key=lambda x: x[1], reverse=True)
        return lead_scores

    def save(self):
        data = {
            "entities": [
                {
                    "entity_id": e.entity_id,
                    "entity_type": e.entity_type,
                    "attributes": e.attributes,
                    "aliases": list(e.aliases),
                }
                for e in self.entities.values()
            ],
            "edges": [
                {
                    "source": u,
                    "target": v,
                    "type": data.get('type'),
                    "confidence": data.get('confidence'),
                    "timestamp": data.get('timestamp'),
                    "metadata": {k: v for k, v in data.items() if k not in ['type', 'confidence', 'timestamp']},
                }
                for u, v, data in self.graph.edges(data=True)
            ],
        }
        self.graph_file.write_text(json.dumps(data, indent=2), encoding='utf-8')

    def load(self):
        data = json.loads(self.graph_file.read_text(encoding='utf-8'))
        for e_data in data.get("entities", []):
            entity = Entity(
                entity_id=e_data["entity_id"],
                entity_type=e_data["entity_type"],
                attributes=e_data.get("attributes", {}),
                aliases=set(e_data.get("aliases", [])),
            )
            self.add_entity(entity)
        for edge_data in data.get("edges", []):
            relation = Relation(
                source_id=edge_data["source"],
                target_id=edge_data["target"],
                relation_type=edge_data["type"],
                confidence=edge_data.get("confidence", 0.5),
                timestamp=edge_data.get("timestamp", 0.0),
                metadata=edge_data.get("metadata", {}),
            )
            self.add_relation(relation)

class TorProxyConfig:
