class TorCrawler:
    def __init__(self, tor_config: TorProxyConfig, output_dir: str = "dark_web_data"):
        self.tor_config = tor_config
        self.output_dir = Path(output_dir)
        self.output_dir.mkdir(exist_ok=True, parents=True)
        self.visited_urls: Set[str] = set()

    async def create_context(self, browser: Browser) -> BrowserContext:
        profile = DeviceFingerprintRandomizer.get_random_profile()
        context = await browser.new_context(
            proxy={"server": self.tor_config.proxy_url},
            user_agent=profile["user_agent"],
            viewport=profile["viewport"],
            screen=profile["screen"],
            timezone_id=profile["timezone_id"],
            locale=profile["locale"],
            has_touch=profile["has_touch"],
            color_scheme=profile["color_scheme"],
            ignore_https_errors=True,
            java_script_enabled=True,
        )
        return context

    async def crawl(self, seed_urls: List[str], max_pages: int = 100):
        async with async_playwright() as p:
            browser = await p.firefox.launch(headless=True)
            context = await self.create_context(browser)
            results = []
            queue = seed_urls.copy()
            while queue and len(results) < max_pages:
                url = queue.pop(0)
                if url in self.visited_urls:
                    continue
                page = await context.new_page()
                try:
                    response = await page.goto(url, wait_until="networkidle", timeout=60000)
                    if not response or response.status >= 400:
                        await page.close()
                        continue
                    await asyncio.sleep(random.uniform(2, 5))
                    title = await page.title()
                    html = await page.content()
                    text = await page.inner_text("body")
                    self.visited_urls.add(url)
                    result = {
                        "url": url,
                        "title": title,
                        "text": text[:10000],
                        "html_length": len(html),
                        "timestamp": time.time(),
                    }
                    results.append(result)
                except Exception as e:
                    pass
                finally:
                    await page.close()
                await asyncio.sleep(random.uniform(3, 8))
            await context.close()
            await browser.close()
        return results

class PDFReportExporter:
    def __init__(self):
        self.styles = getSampleStyleSheet()
        self._setup_custom_styles()

    def _setup_custom_styles(self):
        self.styles.add(ParagraphStyle(
            name='CustomTitle',
            parent=self.styles['Heading1'],
            fontSize=24,
            textColor=colors.HexColor('#1a1a1a'),
            spaceAfter=30,
            alignment=1
        ))
        self.styles.add(ParagraphStyle(
            name='CustomHeading',
            parent=self.styles['Heading2'],
            fontSize=16,
            textColor=colors.HexColor('#2c3e50'),
            spaceAfter=12,
            spaceBefore=12
        ))
        self.styles.add(ParagraphStyle(
            name='CustomBody',
            parent=self.styles['BodyText'],
            fontSize=11,
            textColor=colors.HexColor('#333333'),
            spaceAfter=12,
            leading=14
        ))

    def generate_pdf(self, job_data: dict, output_path: Optional[Path] = None) -> bytes:
        buffer = BytesIO()
        doc = SimpleDocTemplate(
            buffer,
            pagesize=A4,
            rightMargin=72,
            leftMargin=72,
            topMargin=72,
            bottomMargin=18,
        )
        story = []
        title = Paragraph(f"Kutatási Jelentés", self.styles['CustomTitle'])
        story.append(title)
        story.append(Spacer(1, 0.2 * inch))
        metadata = [
            ['Kérdés:', job_data.get('prompt', 'N/A')],
            ['Mód:', job_data.get('mode', 'N/A')],
            ['Státusz:', job_data.get('status', 'N/A')],
            ['Források száma:', str(len(job_data.get('sources', [])))],
        ]
        metadata_table = Table(metadata, colWidths=[2*inch, 4*inch])
        metadata_table.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (0, -1), colors.HexColor('#ecf0f1')),
            ('TEXTCOLOR', (0, 0), (-1, -1), colors.black),
            ('ALIGN', (0, 0), (-1, -1), 'LEFT'),
            ('FONTNAME', (0, 0), (0, -1), 'Helvetica-Bold'),
            ('FONTSIZE', (0, 0), (-1, -1), 10),
            ('GRID', (0, 0), (-1, -1), 1, colors.grey)
        ]))
        story.append(metadata_table)
        story.append(Spacer(1, 0.3 * inch))
        if job_data.get('report'):
            story.append(Paragraph("Jelentés", self.styles['CustomHeading']))
            report_text = job_data['report']
            paragraphs = report_text.split('\n\n')
            for para in paragraphs:
                if para.strip():
                    if para.startswith('#'):
                        para = para.lstrip('#').strip()
                        story.append(Paragraph(para, self.styles['CustomHeading']))
                    else:
                        story.append(Paragraph(para, self.styles['CustomBody']))
        doc.build(story)
        pdf_bytes = buffer.getvalue()
        buffer.close()
        if output_path:
            output_path.write_bytes(pdf_bytes)
        return pdf_bytes

class TimelineGenerator:
    def generate_timeline(self, sources: List[Dict]) -> Dict:
        events = []
        for source in sources:
            if source.get('date'):
                try:
                    date_str = source['date']
                    if 'T' in date_str:
                        dt = datetime.fromisoformat(date_str.replace('Z', '+00:00'))
                    else:
                        dt = datetime.strptime(date_str, '%Y-%m-%d')
                    events.append({
                        "date": dt.isoformat(),
                        "timestamp": dt.timestamp(),
                        "title": source.get('title', 'Untitled'),
                        "url": source.get('url', ''),
                        "reliability": source.get('reliability', 'unknown')
                    })
                except:
                    continue
        events.sort(key=lambda x: x['timestamp'])
        return {
            "events": events,
            "total_events": len(events),
            "date_range": {
                "start": events[0]['date'] if events else None,
                "end": events[-1]['date'] if events else None
            }
        }

class CitationNetworkAnalyzer:
    def analyze_citations(self, sources: List[Dict]) -> Dict:
        nodes = []
        edges = []
        for i, source in enumerate(sources):
            nodes.append({
                "id": f"source_{i}",
                "label": source.get('title', 'Untitled')[:50],
                "url": source.get('url', ''),
                "reliability": source.get('reliability', 'unknown'),
                "authority_score": source.get('authority_score', 0.5)
            })
        for i, source in enumerate(sources):
            source_text = source.get('text', '') + source.get('excerpt', '')
            for j, target in enumerate(sources):
                if i != j:
                    target_url = target.get('url', '')
                    target_domain = self._extract_domain(target_url)
                    if target_domain and target_domain in source_text:
                        edges.append({
                            "source": f"source_{i}",
                            "target": f"source_{j}",
                            "weight": 1
                        })
        return {
            "nodes": nodes,
            "edges": edges,
            "stats": {
                "total_nodes": len(nodes),
                "total_edges": len(edges),
                "average_citations": len(edges) / max(len(nodes), 1)
            }
        }

    def _extract_domain(self, url: str) -> str:
        try:
            parsed = urlparse(url)
            return parsed.netloc
        except:
            return ""

class ProgressDashboard:
    def generate_dashboard(self, job_data: Dict) -> Dict:
