class BatchResearchProcessor:
    def __init__(self, orchestrator, max_concurrent: int = 5):
        self.orchestrator = orchestrator
        self.max_concurrent = max_concurrent
        self.semaphore = asyncio.Semaphore(max_concurrent)

    async def process_batch(self, queries: List[Dict]) -> List[Dict]:
        tasks = [self._process_single_query(query) for query in queries]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        successful = [r for r in results if not isinstance(r, Exception)]
        failed = [r for r in results if isinstance(r, Exception)]
        return {
            "total": len(queries),
            "successful": len(successful),
            "failed": len(failed),
            "results": successful,
            "errors": [str(e) for e in failed]
        }

    async def _process_single_query(self, query: Dict) -> Dict:
        async with self.semaphore:
            try:
                job_id = hashlib.md5(f"{query['prompt']}{datetime.now().timestamp()}".encode()).hexdigest()[:16]
                job = JobState(
                    job_id=job_id,
                    status=JobStatus.PENDING,
                    mode=ResearchMode(query.get('mode', 'sima')),
                    prompt=query['prompt'],
                    created_at=datetime.now().isoformat(),
                    updated_at=datetime.now().isoformat(),
                    progress=0.0,
                    current_step="Batch processing",
                    time_limit_minutes=query.get('time_limit_minutes', 10)
                )
                mode = query.get('mode', 'sima')
                if mode == 'sima':
                    await self.orchestrator.execute_simple_mode(job)
                elif mode == 'kutatas':
                    await self.orchestrator.execute_research_mode(job)
                elif mode == 'autonom':
                    await self.orchestrator.execute_autonomous_mode(job)
                return {
                    "job_id": job_id,
                    "prompt": query['prompt'],
                    "status": job.status.value,
                    "report_length": len(job.report) if job.report else 0,
                    "sources_count": len(job.sources)
                }
            except Exception as e:
                raise

