        )
        self.available = True
        logger.info("Grok client initialized")

    async def quick_verification(self, claim: str, context: str = "", model: str = "grok-4-fast") -> Dict[str, Any]:
        try:
            claim = sanitize_text(claim)
            context = sanitize_text(context)
            prompt = f"""Ellenőrizd az alábbi állítást.
Állítás: {claim}
Kontextus:
{context[:2000]}
Add meg JSON formátumban:
{{
  "verified": true/false,
  "confidence": 0.0-1.0,
  "verification_result": "rövid magyarázat"
}}
"""
            model_max_tokens = {
                "grok-4": 100000,
                "grok-4-fast": 100000
            }
            response = self.client.chat.completions.create(
                model=model,
                messages=[
                    {"role": "system", "content": "You are a fact-checker."},
                    {"role": "user", "content": prompt}
                ],
                temperature=0.2,
                max_tokens=model_max_tokens.get(model, 100000)
            )
            result_text = response.choices[0].message.content or ""
            result_text = sanitize_text(result_text)
            try:
                json_start = result_text.find('{')
                json_end = result_text.rfind('}') + 1
                if json_start != -1 and json_end > json_start:
                    result = json.loads(result_text[json_start:json_end])
                else:
                    result = {
                        "verified": False,
                        "confidence": 0.5,
                        "verification_result": result_text
                    }
            except json.JSONDecodeError:
                result = {
                    "verified": False,
                    "confidence": 0.5,
                    "verification_result": result_text
                }
            logger.info(f"Grok verification completed: {result['verified']}")
            return result
        except Exception as e:
            logger.error(f"Grok verification error: {str(e)}")
            raise

